import { readdirSync, readFileSync } from 'node:fs';
import { describe, expect, it } from 'vitest';

// Generated by `marmeon make:auth` — a form with named fields must say it posts: before the page is interactive (or when its
// script fails to load), Enter submits a form without `method` as a GET, and the fields land in the address — a password in the
// history and in logs. A form without named fields sends nothing that way.

const views = new URL('./views/', import.meta.url);

describe('the forms of the views', () => {
  it('post whenever a field has a name', () => {
    const offenders: string[] = [];
    for (const file of readdirSync(views).filter((name) => name.endsWith('.tsx'))) {
      const source = readFileSync(new URL(file, views), 'utf8');
      for (const [form] of source.matchAll(/<form\b[\s\S]*?<\/form>/g)) {
        // The attributes come before `onSubmit`, whose arrow function has a `>` of its own.
        const attributes = form.slice(0, form.indexOf('onSubmit'));
        if (/\sname=/.test(form) && !/\smethod="post"/.test(attributes)) offenders.push(file);
      }
    }
    expect(offenders, 'a form with named fields and no method="post"').toEqual([]);
  });

  it('show the "keep me signed in" checkbox only when the page says remember-me is on', () => {
    const source = readFileSync(new URL('Login.tsx', views), 'utf8');
    const checkbox = source.indexOf('name="remember"');
    expect(checkbox).toBeGreaterThan(-1);
    const guard = source.lastIndexOf('{rememberOffered && (', checkbox);
    expect(guard, 'the checkbox sits in {rememberOffered && (…)}').toBeGreaterThan(-1);
    expect(source.slice(guard, checkbox)).not.toContain(')}');
  });

  it('end the recovery codes with a "Done" link that works without JavaScript and closes the layer with it', () => {
    const source = readFileSync(new URL('RecoveryCodes.tsx', views), 'utf8');
    expect(source).toContain('<Link');
    expect(source).toContain('route="auth.two-factor"');
    expect(source).not.toContain('<button');
    // The link navigates to the settings page unless a layer takes the click: only then the default is prevented and the layer closes.
    const close = source.indexOf('layer.close()');
    expect(close).toBeGreaterThan(-1);
    const prevented = source.lastIndexOf('event.preventDefault()', close);
    expect(prevented, 'event.preventDefault() before layer.close()').toBeGreaterThan(-1);
    expect(source.lastIndexOf('if (!layer.isLayer) return;', prevented), 'a page (not a layer) keeps the link').toBeGreaterThan(-1);
  });
});

describe('the middleware that shares the app’s props', () => {
  it('leaves a route that is not the app’s before any share(), and asks again in the lazy auth prop', () => {
    const source = readFileSync(new URL('./middleware/ShareAuthProps.ts', import.meta.url), 'utf8');
    const handle = source.slice(source.indexOf('handle('));
    const early = handle.indexOf('if (!this.#auth.ownsRoute()) return next();');
    expect(early, 'an early return on a route that is not the app’s').toBeGreaterThan(-1);
    expect(early).toBeLessThan(handle.indexOf('.share('));
    expect(handle.slice(handle.indexOf("share('auth'")), 'the lazy auth prop asks ownsRoute() again').toContain('this.#auth.ownsRoute() ?');
  });
});
